import socket,time,json,urllib.request,urllib.error,pathlib
print(json.dumps({'resolver':pathlib.Path('/etc/resolv.conf').read_text()}))
for h in ['api.anthropic.com','platform.claude.com','claude.ai']:
 t=time.monotonic()
 try:
  socket.getaddrinfo(h,443)
  print(json.dumps({'host':h,'dns':'PASS','seconds':time.monotonic()-t}))
 except OSError as e:print(json.dumps({'host':h,'dns':str(e),'seconds':time.monotonic()-t}));continue
 try:
  x=urllib.request.urlopen('https://'+h+'/',timeout=15)
  print(json.dumps({'host':h,'https_status':x.status}))
 except urllib.error.HTTPError as e:print(json.dumps({'host':h,'https_status':e.code}))
 except Exception as e:print(json.dumps({'host':h,'https_error':str(e)}))

